'use client';

import { RemovableChip } from './components/ui/removable-chip';
import { useState } from 'react';
export default function Example() {
  const [tags, setTags] = useState(['프론트엔드', '디자인']);
  return <>{tags.map(tag => <RemovableChip key={tag} removeLabel={tag + ' 태그 삭제'} onRemove={() => setTags(current => current.filter(value => value !== tag))}>{tag}</RemovableChip>)}</>;
}
